// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the depositor address and the deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero address (EOA) and amount > 0 and within balanceable range
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // fund depositor with the amount so they can send
        vm.deal(depositor, amount);

        // record previous depositsCount
        uint256 before = c.depositsCount();

        // have depositor send ETH to c via receive()
        vm.prank(depositor);
        (bool ok, ) = address(c).call{value: amount}("");
        // the call should not revert for the reference; record whether it succeeded
        // but we only assert the general property below by reading depositsCount

        uint256 after = c.depositsCount();

        // General rule: any successful ETH send (amount >=1) increments depositsCount by exactly 1.
        // We assert that the contract's depositsCount after the receive equals before + 1.
        // This holds for the reference implementation for all admissible inputs, but the mutant
        // that forbids increases will fail this assertion for some inputs.
        assertTrue(after == before + 1);
    }
}

