pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount to send and sender address
    function testFuzz_property(uint256 amount, address sender) public {
        // keep amount within reasonable gas/ETH bounds but allow zero as admissible
        amount = bound(amount, 0, 1 ether);
        // avoid the zero address as a sender for vm.prank semantics
        if (sender == address(0)) sender = address(1);

        // record before
        uint256 before = c.depositsCount();

        // fund the sender and send ETH to c via receive()
        vm.deal(sender, amount);
        vm.prank(sender);
        // perform the payable call to trigger receive()
        (bool ok, ) = address(c).call{value: amount}("");
        // We observe c only via its public getter
        uint256 after = c.depositsCount();

        // General property: for the correct contract, any deposit increases depositsCount by exactly 1
        // (the mutant disallows any increase and will break for some amount/sender)
        assertTrue(after == before + (ok ? 1 : 0));
    }
}

