pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 amount) public {
        // Keep amount within a reasonable wide domain: allow zero and large values
        // but the interesting behavior requires a payable transfer; allow amount > 0.
        vm.assume(sender != address(0));
        // fund the sender so they can send amount
        vm.deal(sender, amount);

        uint256 before = c.depositsCount();

        bool ok;
        // perform the payable call to receive() from the fuzzed sender with fuzzed amount
        vm.prank(sender);
        try c.call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterCount = c.depositsCount();

        // General rule: for any sender and any nonzero amount that successfully sent,
        // the correct contract increments depositsCount by exactly 1.
        // We assert a property that must hold for the reference contract for ALL inputs:
        // if the low-level call succeeded (ok == true) then after == before + 1.
        // The mutant that forbids any increase will make this assertion fail for some inputs.
        if (ok) {
            assertTrue(afterCount == before + 1);
        } else {
            // If the call reverted, we still assert a true statement about c: no change occurred
            // (this branch is admissible but does not distinguish the mutant); keep it consistent.
            assertTrue(afterCount == before);
        }
    }
}

