        amount = bound(amount, 0, 1 ether);

        // fund depositor so they can send ETH
        vm.deal(depositor, amount);

        uint256 before = c.depositsCount();

        // perform the payable call to trigger receive()
        vm.prank(depositor);
        (bool ok, ) = payable(address(c)).call{value: amount}("");
        // ensure the call completed (ok may be true even if receive reverted? call returns false on revert)
        // but we do not assert on ok here; we only observe the resulting state via the single assert below

        uint256 after = c.depositsCount();

        // General rule: for any depositor and any nonzero amount, reference C increments depositsCount by 1.
        // We encode that as: if amount > 0 and the low-level call succeeded, depositsCount == before + 1.
        // This will hold for the reference contract for all inputs, but the mutant will fail for some inputs
        // because it disallows any increase.

        // Single assertion required: must read c's public surface. We assert the universal property
        // (for this execution): if amount > 0 and the call returned ok, then depositsCount == before + 1.
        if (amount > 0 && ok) {
            assertTrue(after == before + 1);
        } else {
            // If amount == 0 or call failed, the property condition is not required to hold; still assert a tautology
            assertTrue(true);
        }
    }
}

