pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: an actor address and an amount of wei to send.
    // The general rule: for any external caller (EOA) and any positive value, calling receive() should succeed
    // and therefore be observable as a successful call; the mutant's receive() reverts for some inputs.
    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: actor must be nonzero and not the contract itself, amount in a reasonable range
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // Keep amount wide but avoid absurdly huge amounts that would cause overflow in the test harness
        amount = bound(amount, 0, 1 ether);

        // fund the actor so it can send
        vm.deal(actor, amount);

        bool ok;
        // perform the external payable call from the fuzzed actor to trigger receive()
        vm.prank(actor);
        try c.call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract's receive accepts any payable call (including zero? we allowed zero) without reverting
        // but to make the property strict we only assert for the admissible case when amount > 0: such a deposit must not revert.
        // Single assertion: for any admissible inputs (actor != 0, actor != this, amount in [0,1e18]), if amount > 0
        // then the reference contract would have succeeded; the mutant (that has require(false)) will fail for some inputs.
        if (amount > 0) {
            assertTrue(ok);
        } else {
            // when amount == 0 we do not require success (some implementations may accept or reject zero-value calls)
            assertTrue(true);
        }
    }
}

