        // depositsCount increased by exactly 1.
        if (ok) {
            assertTrue(c.depositsCount() == before + 1);
        } else {
            // If call failed, the reference implementation would never fail for an EOA deposit,
            // so when using the correct C this branch should be unreachable across all inputs.
            // But to keep a single assertTrue as required, assert the negation: when ok==false,
