pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzing initialCount and sentValue: the fuzzer will search values that can trigger wraparound
    function testFuzz_property(uint256 initialCount, uint256 sentValue) public {
        // keep within uint range (already is), but bound sentValue to not exceed balance we give the actor
        address depositor = address(0xABCD);
        // Fund depositor so it can send sentValue (bound to reasonable max)
        uint256 maxSend = type(uint256).max / 2; // keep huge but bounded
        if (sentValue > maxSend) sentValue = sentValue % (maxSend + 1);

        // Arrange: set c.depositsCount to initialCount by directly manipulating via constructor-like sequence:
        // We cannot directly set depositsCount, but we can simulate by repeatedly calling receive via a helper actor.
        // To avoid costly loops in fuzzing, we instead deploy a fresh C (already done) and if we need to set a large
        // initialCount, we skip exhaustive setup and just observe the universal property for the starting value.
        // However, we can still ensure the depositor has balance to perform the deposit.

        vm.deal(depositor, sentValue);
        uint256 before = c.depositsCount();

        // The property concerns that after a successful receive, depositsCount >= before.
        // Call receive by performing a plain value transfer from depositor to c.
        vm.prank(depositor);
        // perform low-level transfer which triggers receive()
        // Use try/catch on payable call via address(c).call{value: sentValue}("") to detect success
        bool ok;
        try address(c).call{value: sentValue}("") {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = c.depositsCount();

        // The reference ensures that if the call succeeded (ok==true), then after >= before.
        // The mutant can allow overflow/wrap making after < before for some inputs — fuzz will find such inputs.
        assertTrue(!ok || after >= before);
    }
}

