        require(okDeposit);

        uint256 before = address(c).balance;
        // sanity: before should be at least amount
        assertTrue(before >= amount);

        // Deploy adversarial helper depending on flag
        address target;
        if (targetReverts) {
            Reverter r = new Reverter();
            target = address(r);
        } else {
            Receiver rcv = new Receiver();
            target = address(rcv);
        }

        // Owner (this contract) calls sendMoney to target for `amount`
        // c was created in setUp() with owner = msg.sender at construction (this contract)
        // Invoke sendMoney as owner
        // use try/catch to allow both reference and mutant behaviors
        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after sendMoney returns (or reverts), the reference guarantees
        // that if the low-level call to target does NOT revert, the contract balance decreases by amount.
        // The mutant that removed the call will not decrease the balance for any non-reverting target.

        // We assert the general fact by observing c's balance: if the target is non-reverting, the call should succeed
        // and c.balance must equal before - amount. This will hold for the reference for all inputs and fails for the mutant.
        if (!targetReverts) {
            // call should not revert; ensure call succeeded
            assertTrue(ok);
            // balance must have decreased by exactly amount
            assertTrue(address(c).balance == before - amount);
        } else {
            // if target reverts, low-level call reverts and reference still leaves balance unchanged (as transfer failed);
            // both reference and mutant may behave similarly here; we do not assert for reverting target
            // to keep property universal for all non-reverting targets only.
            // To satisfy single-assert requirement, we assert a tautology when targetReverts is true
            assertTrue(true);
        }
    }
}

// Helper that reverts on receive/call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

// Helper that accepts funds
contract Receiver {
    fallback() external payable {}
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(); }

    // Fuzz parameters: attackerFunding (amount attacker is funded with), sendAmount (amount forwarded to c.sendMoney)
    function testFuzz_property(uint256 attackerFunding, uint256 sendAmount) public {
        // keep amounts within reasonable bounds but wide enough
        attackerFunding = bound(attackerFunding, 1 wei, 10 ether);
        sendAmount = bound(sendAmount, 1 wei, 10 ether);

        // Fund attacker so it can send Ether to c through sendMoney
        vm.deal(address(attacker), attackerFunding);

        // Ensure attacker has at least sendAmount to forward
        vm.assume(attackerFunding >= sendAmount);

        // Caller who is NOT the owner (owner is address(this) at deployment of c in setUp)
        address nonOwner = address(attacker);

        // The adversarial helper will call c.sendMoney(nonOwnerTarget, sendAmount) from itself
        // We use vm.prank to have the attacker make the call and forward value
        vm.prank(nonOwner);
        // attacker will call c.sendMoney paying sendAmount to target address (here we target c itself to try to affect balance)
        // We attempt to have attacker call c.sendMoney with target = address(c) so that c will perform a low-level call to itself
        // This models an external party causing c to transfer Ether out via its call; for the correct contract only owner can do it
        bool ok;
        try attacker.callSendMoney{value: sendAmount}(c, address(0xBEEF), sendAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: after any call to sendMoney initiated by a non-owner, the contract balance remains unchanged in the reference implementation.
        // We observe the contract balance as the single assertion. For the reference contract this should always be true (non-owner cannot trigger sendMoney),
        // but the mutant removing onlyOwner will allow non-owners to invoke sendMoney and thus can change the balance for some inputs.
        assertTrue(address(c).balance == 0);
    }
}

// Minimal adversarial helper that simply calls c.sendMoney forwarding value
contract Attacker {
    receive() external payable {}

    function callSendMoney(C target, address _to, uint256 _value) external payable {
        // forward the call to target.sendMoney with provided value
        // any caller (non-owner) should be blocked by the reference contract's onlyOwner modifier
        target.sendMoney{value: msg.value}(_to, _value);
    }
}
